using System;using System.Collections.Generic;using System.ComponentModel;using System.Linq;using System.Net;using System.Runtime.InteropServices;using System.IO;using System.Text.RegularExpressions;
namespace ServiceTool{
internal sealed class ServiceListener{internal uint Pid;internal string Address;internal int Port;internal string Display {get{return Address+":"+Port;}}}
internal sealed class ServiceEndpointInfo{internal string Summary;internal List<string> HttpAddresses=new List<string>();internal uint Pid;internal List<ServiceListener> Listeners=new List<ServiceListener>();internal List<string> Checks=new List<string>();}
internal static class ServiceEndpoints{
[DllImport("iphlpapi.dll",SetLastError=true)]static extern uint GetExtendedTcpTable(IntPtr table,ref int size,bool order,int family,int kind,uint reserved);
internal static List<ServiceListener> Listeners(uint pid){var result=new List<ServiceListener>();foreach(int family in new[]{2,23}){int size=0;uint error=GetExtendedTcpTable(IntPtr.Zero,ref size,false,family,3,0);if(error!=122&&error!=0)throw new Win32Exception((int)error);IntPtr memory=IntPtr.Zero;try{for(int retry=0;retry<4;retry++){if(memory!=IntPtr.Zero)Marshal.FreeHGlobal(memory);memory=Marshal.AllocHGlobal(Math.Max(4,size));error=GetExtendedTcpTable(memory,ref size,false,family,3,0);if(error!=122)break;}if(error!=0)throw new Win32Exception((int)error);int count=Marshal.ReadInt32(memory),stride=family==2?24:56;if(count<0||count>(size-4)/stride)throw new IOException("Некорректный размер таблицы TCP Windows.");for(int n=0;n<count;n++){int start=4+n*stride;uint owner=unchecked((uint)Marshal.ReadInt32(memory,start+(family==2?20:52)));if(owner!=pid)continue;int portOffset=start+(family==2?8:20);int port=Marshal.ReadByte(memory,portOffset)*256+Marshal.ReadByte(memory,portOffset+1);byte[] address=new byte[family==2?4:16];Marshal.Copy(IntPtr.Add(memory,start+(family==2?4:0)),address,0,address.Length);string ip=new IPAddress(address).ToString();result.Add(new ServiceListener{Pid=owner,Address=family==23?"["+ip+"]":ip,Port=port});}}finally{if(memory!=IntPtr.Zero)Marshal.FreeHGlobal(memory);}}return result;}
internal static string TcpAddress(ServiceListener listener){return new UriBuilder("tcp",listener.Address=="[::]"?"::1":listener.Address.StartsWith("[")?listener.Address.Trim('[',']'):listener.Address=="0.0.0.0"?"127.0.0.1":listener.Address,listener.Port).Uri.AbsoluteUri;}
internal static void AddTcpChecks(ServiceEndpointInfo info){foreach(var listener in info.Listeners){string url=TcpAddress(listener);Uri uri;if(Uri.TryCreate(url,UriKind.Absolute,out uri)&&uri.IsLoopback&&!info.Checks.Contains(url))info.Checks.Add(url);}}
internal static ServiceEndpointInfo Inspect(string name){var snapshot=ServiceCatalog.ReadSnapshot();if(!snapshot.Complete)throw new IOException("Не удалось надёжно прочитать список служб. Повтори проверку.");var service=snapshot.Entries.FirstOrDefault(s=>s.Name==name);var result=new ServiceEndpointInfo();if(service==null){result.Summary="Служба больше не зарегистрирована.";return result;}result.Pid=service.ProcessId;if(result.Pid==0){result.Summary="Служба остановлена: действующих портов процесса нет.";return result;}result.Listeners=Listeners(result.Pid);result.Summary="Процесс PID "+result.Pid+". "+(result.Listeners.Count==0?"Слушающие TCP-порты не найдены. HTTP.sys и дочерние процессы требуют отдельной проверки.":"Слушает: "+String.Join(", ",result.Listeners.Select(l=>l.Display)));if(snapshot.Entries.Count(s=>s.ProcessId==result.Pid)>1){result.Summary+=" Процесс общий для нескольких служб: принадлежность адреса неоднозначна.";return result;}
string configuredExe;if(result.Listeners.Count==0){result.HttpAddresses=ServiceHttpSys.Read(checked((int)result.Pid));foreach(string url in result.HttpAddresses){Uri endpoint=new Uri(url);result.Listeners.Add(new ServiceListener{Address=endpoint.Host,Port=endpoint.Port});result.Checks.Add(url);}if(result.Checks.Count>0){result.Summary="HTTP.sys: адрес подтверждён очередью выбранного процесса. Проверяется HTTP-ответ без рабочих команд.";return result;}}
if(ExecutablePaths.TryGetExecutable(service.BinaryPath,out configuredExe))result.HttpAddresses=ServiceHostingConfig.Read(configuredExe).Where(u=>result.Listeners.Any(l=>l.Port==new Uri(u).Port)).ToList();
if(!name.Equals("DK.Banking.Agent",StringComparison.OrdinalIgnoreCase)){AddTcpChecks(result);result.Summary+=" Проверяется принятие TCP-соединения без отправки команд. Это не проверка API или оборудования.";return result;}string exe;if(!ExecutablePaths.TryGetExecutable(service.BinaryPath,out exe))return result;string folder=Path.Combine(Path.GetDirectoryName(exe),"configs");foreach(string file in new[]{"appsettings.json","appsettings.Production.json"}){string path=Path.Combine(folder,file);if(!File.Exists(path))continue;string text=File.ReadAllText(path);foreach(Match match in Regex.Matches(text,"\"Urls\"\\s*:\\s*\"([^\"]+)\"")){foreach(string raw in match.Groups[1].Value.Split(';')){Uri uri;string candidate=raw.Replace("*","127.0.0.1").Replace("+","127.0.0.1");if(!Uri.TryCreate(candidate,UriKind.Absolute,out uri)||uri.Scheme!="http"||!uri.IsLoopback||!result.Listeners.Any(l=>l.Port==uri.Port&&(l.Address=="127.0.0.1"||l.Address=="0.0.0.0")))continue;string check=new UriBuilder("http","127.0.0.1",uri.Port,"/Info/Ping").Uri.AbsoluteUri;if(!result.HttpAddresses.Contains(new UriBuilder("http","localhost",uri.Port).Uri.AbsoluteUri))result.HttpAddresses.Add(new UriBuilder("http","localhost",uri.Port).Uri.AbsoluteUri);if(!result.Checks.Contains(check))result.Checks.Add(check);}}}if(result.Checks.Count==0)AddTcpChecks(result);result.Summary+=result.Checks.Any(c=>c.StartsWith("http:"))?" HTTP-адрес сопоставлен с портом выбранного процесса.":" HTTP-адрес не подтверждён; доступна проверка TCP без команд.";return result;}
internal static bool StillOwns(string name,string address){var info=Inspect(name);return info.Checks.Contains(address);}
}}
